DECLARE
  v_template_id CRE_DOC_TEMPLATE_MGT.TEMPLATES.TEMPLATE_ID%TYPE;
  v_template_type_code CRE_DOC_TEMPLATE_MGT.TEMPLATES.TEMPLATE_TYPE_CODE%TYPE;
BEGIN
  SELECT t1.template_id, t2.template_type_code
    INTO v_template_id, v_template_type_code
    FROM (
       SELECT template_id
       FROM cre_doc_template_mgt.documents
       GROUP BY template_id
       ORDER BY COUNT(*) DESC
       FETCH FIRST 1 ROWS ONLY
    ) t1
    JOIN cre_doc_template_mgt.templates t2
      ON t1.template_id = t2.template_id;

  DBMS_OUTPUT.PUT_LINE(v_template_id || ',' || v_template_type_code);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
END;
