    SELECT document_id
    FROM (
      SELECT document_id
      FROM CRE_DOC_TEMPLATE_MGT.PARAGRAPHS
      WHERE paragraph_text = 'Brazil'
      INTERSECT
      SELECT document_id
      FROM CRE_DOC_TEMPLATE_MGT.PARAGRAPHS
      WHERE paragraph_text = 'Ireland'
    )
    ORDER BY document_id
  ) LOOP
    IF l_first THEN
      l_first := FALSE;
