  INTO v_owner_id, v_zip_code
  FROM DOG_KENNELS.OWNERS t1
  JOIN DOG_KENNELS.DOGS t2 ON t1.owner_id = t2.owner_id
  JOIN DOG_KENNELS.TREATMENTS t3 ON t2.dog_id = t3.dog_id
  GROUP BY t1.owner_id, t1.zip_code
  ORDER BY SUM(t3.cost_of_treatment) DESC
  FETCH FIRST 1 ROWS ONLY;

  DBMS_OUTPUT.PUT_LINE(v_owner_id || ',' || v_zip_code);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
END;
