DECLARE
  v_owner_id DOG_KENNELS.OWNERS.OWNER_ID%TYPE;
  v_zip_code DOG_KENNELS.OWNERS.ZIP_CODE%TYPE;
BEGIN
  SELECT owner_id, zip_code
  INTO v_owner_id, v_zip_code
  FROM (
    SELECT t1.owner_id, t1.zip_code, SUM(t3.cost_of_treatment) AS total_spent
    FROM DOG_KENNELS.OWNERS t1
    JOIN DOG_KENNELS.DOGS t2 ON t1.OWNER_ID = t2.OWNER_ID
    JOIN DOG_KENNELS.TREATMENTS t3 ON t2.DOG_ID = t3.DOG_ID
    GROUP BY t1.OWNER_ID, t1.ZIP_CODE
    ORDER BY total_spent DESC
  )
  WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE(v_owner_id || ',' || v_zip_code);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
END;
