DECLARE
  v_avg_cost DOG_KENNELS.TREATMENTS.COST_OF_TREATMENT%TYPE;
BEGIN
  SELECT AVG(COST_OF_TREATMENT)
  INTO v_avg_cost
  FROM DOG_KENNELS.TREATMENTS;

  FOR r IN (
    SELECT DISTINCT t1.first_name, t1.last_name
    FROM DOG_KENNELS.PROFESSIONALS t1
    JOIN DOG_KENNELS.TREATMENTS t2
      ON t1.professional_id = t2.professional_id
    WHERE t2.cost_of_treatment < v_avg_cost
    ORDER BY t1.first_name, t1.last_name
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(r.first_name || ',' || r.last_name);
  END LOOP;
END;
/

