DECLARE
  CURSOR c_codes IS
    SELECT countrycode
    FROM world_1.countrylanguage
    MINUS
    SELECT countrycode
    FROM world_1.countrylanguage
    WHERE language = 'English';
  l_line VARCHAR2(32767);
BEGIN
  FOR r IN c_codes LOOP
    IF l_line IS NULL THEN
      l_line := r.countrycode;
    ELSE
      l_line := l_line || ',' || r.countrycode;
    END IF;
  END LOOP;

  IF l_line IS NOT NULL THEN
    DBMS_OUTPUT.PUT_LINE(l_line);
  END IF;
END;
/

BEGIN
  FOR rec IN (
    SELECT DISTINCT countrycode
    FROM world_1.countrylanguage
    WHERE language <> 'English'
  )
  LOOP
    DBMS_OUTPUT.put_line(rec.countrycode);
  END LOOP;
END;
/

DECLARE
  v_line VARCHAR2(32767);
BEGIN
  SELECT LISTAGG(countrycode, ',') WITHIN GROUP (ORDER BY countrycode)
    INTO v_line
    FROM (
      SELECT DISTINCT countrycode
      FROM world_1.countrylanguage
      WHERE language != 'English'
    );

  DBMS_OUTPUT.PUT_LINE(v_line);
END;
/

BEGIN
  FOR r IN (
    SELECT code
    FROM (
      SELECT code FROM world_1.country WHERE governmentform != 'Republic'
      MINUS
      SELECT countrycode FROM world_1.countrylanguage WHERE language = 'English'
    )
    ORDER BY code
  )
  LOOP
    DBMS_OUTPUT.PUT_LINE(r.code);
  END LOOP;
END;
