DECLARE
  v_first BOOLEAN := TRUE;
BEGIN
  FOR r IN (
    SELECT DISTINCT t2.name
    FROM world_1.country t1
    JOIN world_1.city t2 ON t2.countrycode = t1.code
    WHERE t1.continent = 'Europe'
      AND t1.name NOT IN (
        SELECT t3.name
        FROM world_1.country t3
        JOIN world_1.countrylanguage t4 ON t3.code = t4.countrycode
        WHERE t4.isofficial = 'T'
          AND t4.language = 'English'
      )
    ORDER BY t2.name
  ) LOOP
    IF v_first THEN
      DBMS_OUTPUT.PUT(r.name);
      v_first := FALSE;
    ELSE
      DBMS_OUTPUT.PUT(',' || r.name);
    END IF;
  END LOOP;
  DBMS_OUTPUT.NEW_LINE;
END;
/

