    SELECT t1.name AS country_name, COUNT(t2.language) AS lang_count
    FROM world_1.country t1
    JOIN world_1.countrylanguage t2
      ON t1.code = t2.countrycode
    GROUP BY t1.name
    HAVING COUNT(*) > 2
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(r.country_name || ',' || r.lang_count);
  END LOOP;
END;
