DECLARE
  v_avg_population NUMBER;
BEGIN
  SELECT AVG(population) INTO v_avg_population FROM world_1.city;

  FOR r IN (
    SELECT COUNT(*) AS city_count, district
    FROM world_1.city
    WHERE population > v_avg_population
    GROUP BY district
    ORDER BY district
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(r.city_count) || ',' || r.district);
  END LOOP;
END;
/

DECLARE
  l_avg_pop NUMBER;
BEGIN
  SELECT AVG(population) INTO l_avg_pop FROM world_1.city;

  FOR rec IN (
    SELECT district, COUNT(*) cnt
    FROM world_1.city
    WHERE population > l_avg_pop
    GROUP BY district
    ORDER BY district
  )
  LOOP
    DBMS_OUTPUT.PUT_LINE(rec.cnt || ',' || rec.district);
  END LOOP;
END;
 /

