DECLARE
  v_record_company ORCHESTRA.ORCHESTRA.RECORD_COMPANY%TYPE;
BEGIN
  SELECT record_company
  INTO v_record_company
  FROM (
    SELECT record_company
    FROM orchestra.orchestra
