BEGIN
  SELECT COUNT(*)
  INTO l_count
  FROM CAR_1.CAR_MAKERS T1
  JOIN CAR_1.MODEL_LIST T2 ON T1.ID = T2.MAKER
  WHERE T1.FULLNAME = 'American Motor Company';

  DBMS_OUTPUT.PUT_LINE('American Motor Company,' || l_count);
END;
/

BEGIN
