BEGIN
  FOR r IN (
    SELECT DISTINCT T2.MODEL
    FROM CAR_1.CAR_NAMES T1
    JOIN CAR_1.MODEL_LIST T2 ON T1.MODEL = T2.MODEL
    JOIN CAR_1.CAR_MAKERS T3 ON T2.MAKER = T3.ID
    JOIN CAR_1.CARS_DATA T4 ON T1.MAKEID = T4.ID
    WHERE T3.FULLNAME = 'General Motors' OR T4.WEIGHT > 3500
  ) LOOP
    DBMS_OUTPUT.PUT_LINE(r.MODEL);
