DECLARE
  CURSOR c_years IS
    SELECT DISTINCT year
    FROM CAR_1.CARS_DATA
    WHERE weight BETWEEN 3000 AND 4000
    ORDER BY year;
  v_first BOOLEAN := TRUE;
BEGIN
  FOR r IN c_years LOOP
    IF v_first THEN
      v_first := FALSE;
    ELSE
      DBMS_OUTPUT.PUT(',');
    END IF;
    DBMS_OUTPUT.PUT(r.year);
  END LOOP;
  DBMS_OUTPUT.NEW_LINE;
END;
/

