DECLARE
  v_acc CAR_1.CARS_DATA.ACCELERATE%TYPE;
  v_cnt NUMBER;
BEGIN
  SELECT ACCELERATE
  INTO v_acc
  FROM CAR_1.CARS_DATA
  ORDER BY HORSEPOWER DESC
  FETCH FIRST 1 ROWS ONLY;

  SELECT COUNT(*)
  INTO v_cnt
  FROM CAR_1.CARS_DATA
  WHERE ACCELERATE > v_acc;

  DBMS_OUTPUT.PUT_LINE(TO_CHAR(v_cnt));
END;
