DECLARE
  l_model CAR_1.CAR_NAMES.MODEL%TYPE;
BEGIN
  SELECT model
    INTO l_model
  FROM (
    SELECT t1.model
    FROM CAR_1.CAR_NAMES t1
    JOIN CAR_1.CARS_DATA t2
      ON t1.makeid = t2.id
    WHERE t2.cylinders = 4
    ORDER BY t2.horsepower DESC
  )
  WHERE ROWNUM = 1;

  DBMS_OUTPUT.PUT_LINE(l_model);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('');
END;
