DECLARE
  CURSOR c IS
    SELECT t2.makeid, t2.make
    FROM car_1.cars_data t1
    JOIN car_1.car_names t2 ON t1.id = t2.makeid
    WHERE t1.horsepower > (SELECT MIN(horsepower) FROM car_1.cars_data)
      AND t1.cylinders <= 3;
BEGIN
  FOR r IN c LOOP
    DBMS_OUTPUT.PUT_LINE(r.makeid || ',' || r.make);
  END LOOP;
END;
