DECLARE
  l_line   VARCHAR2(32767);
  l_first  BOOLEAN := TRUE;
BEGIN
  FOR r IN (
    SELECT DISTINCT t1.name
    FROM singer.singer t1
    JOIN singer.song t2 ON t1.singer_id = t2.singer_id
    WHERE t2.sales > 300000
    ORDER BY t1.name
  ) LOOP
    IF l_first THEN
      l_line := r.name;
      l_first := FALSE;
    ELSE
      IF LENGTH(l_line) + 1 + LENGTH(r.name) > 32767 THEN
        DBMS_OUTPUT.PUT_LINE(l_line);
        l_line := r.name;
      ELSE
        l_line := l_line || ',' || r.name;
      END IF;
    END IF;
  END LOOP;

  IF l_line IS NOT NULL THEN
    DBMS_OUTPUT.PUT_LINE(l_line);
  END IF;
END;
/

