declare
  l_cursor integer;
  l_sql    varchar2(32767) := 'select * from EMPLOYEE_HIRE_EVALUATION.HIRING';
  l_colcnt integer;
  l_desc   dbms_sql.desc_tab;
  l_status integer;
  l_val    varchar2(32767);
  l_line   varchar2(32767);
begin
  l_cursor := dbms_sql.open_cursor;
  dbms_sql.parse(l_cursor, l_sql, dbms_sql.native);
  dbms_sql.describe_columns(l_cursor, l_colcnt, l_desc);

  for i in 1..l_colcnt loop
    dbms_sql.define_column(l_cursor, i, l_val, 32767);
  end loop;

  l_status := dbms_sql.execute(l_cursor);

  l_line := null;
  for i in 1..l_colcnt loop
    if i > 1 then l_line := l_line || ','; end if;
    l_line := l_line || l_desc(i).col_name;
  end loop;
  dbms_output.put_line(l_line);

  while dbms_sql.fetch_rows(l_cursor) > 0 loop
    l_line := null;
    for i in 1..l_colcnt loop
      l_val := null;
      dbms_sql.column_value(l_cursor, i, l_val);
      if i > 1 then l_line := l_line || ','; end if;
      l_line := l_line || replace(replace(nvl(l_val, ''), chr(13), ' '), chr(10), ' ');
    end loop;
    dbms_output.put_line(l_line);
  end loop;

  dbms_sql.close_cursor(l_cursor);
exception
  when others then
    if dbms_sql.is_open(l_cursor) then
      dbms_sql.close_cursor(l_cursor);
    end if;
    raise;
end;

