DECLARE
  l_line VARCHAR2(32767);
  l_token VARCHAR2(4000);
BEGIN
  FOR r IN (
    SELECT t1.name
    FROM poker_player.people t1
    JOIN poker_player.poker_player t2
      ON t1.people_id = t2.people_id
    ORDER BY t2.earnings DESC
  ) LOOP
    l_token := r.name;
    IF l_line IS NULL THEN
      l_line := l_token;
    ELSIF LENGTH(l_line) + 1 + LENGTH(l_token) > 32767 THEN
      dbms_output.put_line(l_line);
      l_line := l_token;
    ELSE
      l_line := l_line || ',' || l_token;
    END IF;
  END LOOP;
  IF l_line IS NOT NULL THEN
    dbms_output.put_line(l_line);
  END IF;
END;
