DECLARE
  v_first_name   WTA_1.PLAYERS.FIRST_NAME%TYPE;
  v_country_code WTA_1.PLAYERS.COUNTRY_CODE%TYPE;
  v_birth_date   VARCHAR2(8);
BEGIN
  SELECT t1.first_name, t1.country_code, TO_CHAR(t1.birth_date, 'YYYYMMDD')
    INTO v_first_name, v_country_code, v_birth_date
    FROM WTA_1.PLAYERS t1
    JOIN WTA_1.MATCHES t2
      ON t1.player_id = t2.winner_id
   ORDER BY t2.winner_rank_points DESC
   FETCH FIRST 1 ROWS ONLY;

  DBMS_OUTPUT.PUT_LINE(v_first_name || ',' || v_country_code || ',' || v_birth_date);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
END;
